import{_ as e,o as d,c as o,a2 as a}from"./chunks/framework.CNDaxUod.js";const m=JSON.parse('{"title":"Roles and permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/roles.md","filePath":"guide/roles.md"}'),s={name:"guide/roles.md"};function r(n,t,i,c,h,p){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="roles-and-permissions" tabindex="-1">Roles and permissions <a class="header-anchor" href="#roles-and-permissions" aria-label="Permalink to &quot;Roles and permissions&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Role</th><th>How you get it</th><th>What it grants</th></tr></thead><tbody><tr><td>Operator</td><td>Holds the operator token (<code>OPERATOR_TOKEN</code>)</td><td>Everything, including workspace settings, while token sign-in is on</td></tr><tr><td>Workspace admin</td><td>A Google Workspace super or delegated admin (through the <a href="./directory.html">Directory</a>), or in the SAML admin group</td><td>The full console: every standup, workspace settings, deleting archived standups</td></tr><tr><td>Manager (standup admin)</td><td>Ran <code>setup</code>, created the standup in the web app, or was granted <code>admin @user</code></td><td>Configure that standup from Chat or the web app; manage the schedules and time-off requests of people on it</td></tr><tr><td>Participant</td><td>On the standup&#39;s roster: picked in the People grid, <code>add @user</code>, or a member of the Google Group it follows</td><td>Answer, edit, skip, DM self-service, their own page at <code>/app/me</code></td></tr><tr><td>Everyone in the space</td><td>—</td><td><code>status</code>, <code>trends</code>, <code>blockers</code>, <code>blocker</code>, polls, <code>help</code>, and <code>setup</code></td></tr></tbody></table><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Every check in the web app, the <a href="./api.html">JSON API</a>, Chat commands and <a href="./mcp.html">MCP</a> asks for one permission, either across the workspace or on one standup. The roles above are fixed sets of them:</p><table tabindex="0"><thead><tr><th>Permission</th><th>Lets you</th><th>Admin</th><th>Manager</th><th>Participant</th></tr></thead><tbody><tr><td><code>standups.view</code></td><td>See a standup, who is on it and how today is going</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>answers.view</code></td><td>Read each day&#39;s answers</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>blockers.view</code></td><td>See blockers and their updates</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>reports.view</code></td><td>See run history and insights</td><td>✓</td><td>✓</td><td>✓</td></tr><tr><td><code>standups.configure</code></td><td>Change the schedule, questions, mood, escalation and webhook; run now, nudge, close polls</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>standups.archive</code></td><td>Archive a standup and bring it back</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>people.view</code></td><td>See the Team directory</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>people.manage</code></td><td>Add and remove people, mark them required, make managers</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>schedules.manage</code></td><td>Change people&#39;s weeks and days off, decide time-off requests</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>blockers.manage</code></td><td>Resolve anyone&#39;s blocker</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>export</code></td><td>Download answers as CSV</td><td>✓</td><td>✓</td><td></td></tr><tr><td><code>standups.create</code></td><td>Create standups from the web app or API</td><td>✓</td><td></td><td></td></tr><tr><td><code>standups.delete</code></td><td>Delete an archived standup with its history</td><td>✓</td><td></td><td></td></tr><tr><td><code>settings.manage</code></td><td>Workspace settings, setup checks, deleting history</td><td>✓</td><td></td><td></td></tr><tr><td><code>sso.manage</code></td><td>Google sign-in, SAML and token sign-in</td><td>✓</td><td></td><td></td></tr><tr><td><code>tokens.manage</code></td><td>Machine tokens, service MCP tokens, everyone&#39;s MCP tokens</td><td>✓</td><td></td><td></td></tr><tr><td><code>roles.manage</code></td><td>Who is an admin, including the SAML admin group</td><td>✓</td><td></td><td></td></tr></tbody></table><p>A manager&#39;s and a participant&#39;s permissions apply only to their own standups. The API reference names the permission each route needs.</p><p>Notes:</p><ul><li>A standup always keeps at least one admin; removing the last is refused.</li><li>A standup created with no admins (for example from a script with the operator token) is open to configuration by anyone in its space. Name an admin when creating on someone&#39;s behalf.</li><li>The web app and the <a href="./api.html">JSON API</a> share one authorisation model. MCP tools act as the token&#39;s owner and see exactly what that person sees (<a href="./mcp.html">Claude Code and MCP</a>).</li><li>Who may mark someone away is set per standup by its <a href="./schedules.html#who-can-change-what-the-time-off-policy">time-off policy</a>.</li></ul>',8)])])}const u=e(s,[["render",r]]);export{m as __pageData,u as default};
